'use strict';
/**
 * The camp plan's document (#1418), generated by the server with PDFKit.
 *
 * The PDF is tagged for assistive technology (PDF/UA): a structure tree with
 * headings, paragraphs and tables whose header cells name their scope, the
 * document's language, its title shown in the window, and embedded fonts that
 * carry French accents (DejaVu Sans). It is written in the unit's language from
 * `lang/<language>.json`, and from a snapshot only (services/campPlanVersions.js):
 * it never reads the database, so a version's document always matches it.
 *
 * A section with nothing in it is printed "to complete", never left out. The
 * allergies section lists names only in the copy made with `health`; the other
 * copy says where to find them.
 *
 * @module services/campPlanPdf
 */
const path = require('path');
const PDFDocument = require('pdfkit');

const TRANSLATIONS = { en: require('../lang/en.json'), fr: require('../lang/fr.json') };
/** Units of measure the unit's articles use; anything else reads as "each", as the material screen does. */
const EQUIPMENT_UNITS = require('../config/equipment_units.json').units;
const PDF_LANGUAGES = Object.keys(TRANSLATIONS);
const LOCALES = { en: 'en-CA', fr: 'fr-CA' };
const FONT_DIR = path.join(path.dirname(require.resolve('dejavu-fonts-ttf/package.json')), 'ttf');

/**
 * Reasons a version frozen earlier may still hold but that no longer exist (#1423: the outside
 * registry comparison was dropped). A document regenerated from such a version, after an erasure,
 * leaves them out rather than printing their key.
 */
const RETIRED_REASONS = new Set(['sisc_not_compared']);

const PAGE_MARGIN = 54;
const SIZE = { title: 20, h2: 15, h3: 12, body: 10, small: 9 };
const GAP = { section: 0.8, paragraph: 0.35 };
const CELL_PADDING = 4;

/**
 * @param {string} language - en or fr
 * @returns {(key: string, values?: Object) => string} Translate a key, filling {placeholders}
 */
function translator(language) {
  const strings = TRANSLATIONS[language] || TRANSLATIONS.fr;
  return (key, values = {}) => Object.entries(values)
    .reduce((text, [name, value]) => text.split(`{${name}}`).join(String(value)), strings[key] ?? key);
}

/**
 * Generate the plan's PDF from a snapshot.
 *
 * @param {Object} snapshot - From buildPlanSnapshot
 * @param {Object|null} health - The camp's allergies, for the copy that shows them; null otherwise
 * @param {{version: number, submittedAt: Date, language: string, code: string}} meta - `code` is the
 *   version's verification code, printed on the first page and shown in Wampums
 * @returns {Promise<Buffer>} The PDF
 */
function renderPlanPdf(snapshot, health, { version, submittedAt, language, code }) {
  const t = translator(language);
  const locale = LOCALES[language] || LOCALES.fr;
  const day = (value) => (value ? new Intl.DateTimeFormat(locale, { dateStyle: 'long', timeZone: 'UTC' })
    .format(new Date(`${String(value).slice(0, 'YYYY-MM-DD'.length)}T00:00:00Z`)) : '');
  const number = (value) => new Intl.NumberFormat(locale).format(Number(value) || 0);
  const name = snapshot.camp.theme || t('camp_readiness_camp');
  const title = t('camp_plan_pdf_title', { name });

  const doc = new PDFDocument({
    pdfVersion: '1.7', subset: 'PDF/UA', tagged: true, lang: locale, displayTitle: true,
    margin: PAGE_MARGIN, bufferPages: false,
    info: { Title: title, Subject: t('camp_permit_title'), Creator: 'Wampums', CreationDate: submittedAt, ModDate: submittedAt },
  });
  doc.registerFont('body', path.join(FONT_DIR, 'DejaVuSans.ttf'));
  doc.registerFont('bold', path.join(FONT_DIR, 'DejaVuSans-Bold.ttf'));
  doc.font('body').fontSize(SIZE.body);

  const chunks = [];
  doc.on('data', (chunk) => chunks.push(chunk));
  const done = new Promise((resolve, reject) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
  });

  const root = doc.struct('Document');
  doc.addStructure(root);
  const heading = (parent, level, text) => {
    parent.add(doc.struct(level, () => {
      doc.font('bold').fontSize(level === 'H1' ? SIZE.title : level === 'H2' ? SIZE.h2 : SIZE.h3).text(text);
      doc.font('body').fontSize(SIZE.body).moveDown(GAP.paragraph);
    }));
  };
  const paragraph = (parent, text) => {
    parent.add(doc.struct('P', () => {
      doc.font('body').fontSize(SIZE.body).text(text);
      doc.moveDown(GAP.paragraph);
    }));
  };
  const toComplete = (parent) => paragraph(parent, t('camp_permit_state_to_complete'));
  /** A table whose first row is column headers. */
  const table = (parent, headers, rows) => {
    doc.table({
      structParent: parent,
      defaultStyle: { padding: CELL_PADDING, fontSize: SIZE.small },
      data: [
        headers.map((text) => ({ text, type: 'TH', scope: 'column', font: { src: 'bold' } })),
        ...rows.map((row) => row.map((cell) => ({ text: cell === null || cell === undefined || cell === '' ? '—' : String(cell) }))),
      ],
    });
    doc.font('body').fontSize(SIZE.body).moveDown(GAP.section);
  };
  /** A table of facts: each row's first cell names the row. */
  const facts = (parent, rows) => {
    doc.table({
      structParent: parent,
      columnStyles: [{ width: 170 }, '*'],
      defaultStyle: { padding: CELL_PADDING, fontSize: SIZE.small },
      data: rows.map(([label, value]) => [
        { text: label, type: 'TH', scope: 'row', font: { src: 'bold' } },
        { text: value === null || value === undefined || value === '' ? t('camp_permit_state_to_complete') : String(value) },
      ]),
    });
    doc.font('body').fontSize(SIZE.body).moveDown(GAP.section);
  };
  const section = (titleKey, draw) => {
    const sect = doc.struct('Sect');
    root.add(sect);
    heading(sect, 'H2', t(titleKey));
    draw(sect);
    sect.end();
  };

  // Title and what this document is.
  heading(root, 'H1', title);
  paragraph(root, t('camp_plan_pdf_version_line', { version: number(version), date: day(submittedAt.toISOString()) }));
  if (code) {
    paragraph(root, t('camp_plan_pdf_code_line', { code }));
  }
  paragraph(root, t('camp_plan_pdf_disclaimer'));

  const { header } = snapshot;
  section('camp_permit_header_title', (sect) => facts(sect, [
    [t('organization_name'), header.name],
    [t('unit_settings_unit_name'), header.unit],
    [t('camp_permit_scout_group'), (header.scout_groups || []).join(', ')],
    [t('District'), header.district],
    [t('camp_permit_branch'), header.program_section && header.program_section !== 'general'
      ? t(`program_section_${header.program_section}`) : null],
    [t('unit_coeducation_label'), header.coeducation ? t(`unit_coeducation_${header.coeducation}`) : null],
    [t('camp_permit_dates'), t('camp_readiness_upcoming_dates', { from: day(snapshot.camp.date_from), to: day(snapshot.camp.date_to) })],
    [t('camp_permit_days'), number(header.days)],
    [t('camp_permit_youth_count'), header.youth_count === null ? null : number(header.youth_count)],
  ]));

  section('camp_plan_pdf_checklist', (sect) => table(sect,
    [t('camp_plan_pdf_requirement'), t('camp_plan_pdf_state'), t('camp_plan_pdf_details')],
    snapshot.checklist.map((line) => [
      t(`camp_permit_line_${line.key}`),
      `${line.blocking ? `${t('camp_permit_blocking')} ` : ''}${t(`camp_permit_state_${line.state}`)}`,
      line.reasons.filter((reason) => !RETIRED_REASONS.has(reason))
        .map((reason) => t(`camp_permit_reason_${reason}`, countsFor(reason, line, number))).join(' '),
    ])));

  section('camp_plan_pdf_site', (sect) => {
    const { site } = snapshot;
    if (!site) {
      toComplete(sect);
      return;
    }
    facts(sect, [
      [t('camp_plan_pdf_site_name'), site.name],
      [t('camp_plan_pdf_owner'), site.owner_name],
      [t('camp_plan_pdf_address'), [site.address, site.province].filter(Boolean).join(', ')],
      [t('camp_plan_pdf_phone'), site.phone],
      [t('camp_plan_pdf_season'), site.season ? t(`camp_site_season_${site.season}`) : null],
      [t('camp_plan_pdf_accommodation'), (site.camp_accommodation || site.accommodation)
        ? [t(`camp_site_accommodation_${site.camp_accommodation || site.accommodation}`), site.accommodation_note].filter(Boolean).join(' — ')
        : null],
      [t('camp_plan_pdf_heating'), site.heating ? [t(`camp_site_heating_${site.heating}`), site.heating_note].filter(Boolean).join(' — ') : null],
      [t('camp_plan_pdf_insurance'), site.has_own_insurance === null ? null
        : [t(site.has_own_insurance ? 'camp_plan_pdf_yes' : 'camp_plan_pdf_no'), site.insurance_note].filter(Boolean).join(' — ')],
      [t('camp_plan_pdf_on_site_lead'), site.on_site_lead_name],
      [t('camp_plan_pdf_contact_phone'), site.contact_phone || site.phone],
      [t('camp_plan_pdf_hospital'), [site.hospital_name, site.hospital_address, site.hospital_phone].filter(Boolean).join(' — ')],
      [t('camp_plan_pdf_hospital_travel'), site.hospital_travel_minutes === null ? null
        : t('camp_plan_pdf_minutes', { count: number(site.hospital_travel_minutes) })],
      [t('camp_plan_pdf_poison_centre'), site.poison_centre_phone],
      [t('camp_plan_pdf_other_numbers'), site.other_emergency_numbers],
      [t('camp_plan_pdf_directions'), site.directions_url],
      [t('camp_plan_pdf_hospital_directions'), site.hospital_directions_url],
    ]);
  });

  section('camp_plan_pdf_sections', (sect) => snapshot.sections.forEach((entry) => {
    heading(sect, 'H3', t(`camp_plan_section_${entry.key}`));
    if (entry.text) {
      entry.text.split(/\n{2,}/).forEach((block) => paragraph(sect, block));
    } else {
      toComplete(sect);
    }
  }));

  section('camp_plan_section_rain_games', (sect) => {
    if (!snapshot.rain_games.length) {
      toComplete(sect);
      return;
    }
    snapshot.rain_games.forEach((game) => {
      heading(sect, 'H3', game.name);
      if (game.description) {
        paragraph(sect, game.description);
      }
      if (game.material) {
        paragraph(sect, t('camp_plan_pdf_material_line', { material: game.material }));
      }
    });
  });

  section('camp_plan_pdf_schedule', (sect) => snapshot.schedule.forEach((entry) => {
    heading(sect, 'H3', [day(entry.date), entry.title].filter(Boolean).join(' — '));
    if (!entry.title) {
      paragraph(sect, t('camp_plan_pdf_day_untitled'));
    }
    if (entry.notes) {
      paragraph(sect, entry.notes);
    }
    if (!entry.lines.length) {
      toComplete(sect);
      return;
    }
    table(sect, [t('time'), t('activity_label'), t('yearly_planner_responsible'), t('yearly_planner_logistic_notes')],
      entry.lines.map((line) => [
        line.start_time,
        line.duration_minutes ? `${line.name} (${t('camp_plan_pdf_minutes', { count: number(line.duration_minutes) })})` : line.name,
        [...line.leaders.map((leader) => (leader.left ? `${leader.name} ${t('yearly_planner_leader_left')}` : leader.name)),
          line.responsable].filter(Boolean).join(', '),
        line.description,
      ]));
  }));

  section('camp_plan_pdf_team', (sect) => {
    if (!snapshot.team.length) {
      toComplete(sect);
    } else {
      table(sect, [t('camp_plan_pdf_name'), t('camp_plan_pdf_role'), t('camp_plan_pdf_certifications')],
        snapshot.team.map((member) => [
          member.active_member ? member.name : `${member.name} ${t('yearly_planner_leader_left')}`,
          t(`camp_roster_role_${member.team_role}`),
          member.certifications.map((key) => t(`volunteer_requirement_${key}`)).join(', '),
        ]));
    }
    if (snapshot.volunteers.length) {
      heading(sect, 'H3', t('camp_plan_pdf_volunteers'));
      table(sect, [t('camp_plan_pdf_shifts'), t('camp_plan_pdf_volunteer_count')],
        snapshot.volunteers.map((entry) => [t(`volunteer_type_${entry.type}`), number(entry.count)]));
    }
  });

  section('camp_plan_pdf_youth', (sect) => {
    if (!snapshot.youth.length) {
      toComplete(sect);
      return;
    }
    table(sect, [t('camp_plan_pdf_name'), t('camp_plan_pdf_age')],
      snapshot.youth.map((person) => [`${person.first_name} ${person.last_name}`, person.age_at_camp === null ? null : number(person.age_at_camp)]));
  });

  section('camp_plan_pdf_allergies', (sect) => {
    if (!health) {
      paragraph(sect, t('camp_plan_pdf_allergies_elsewhere'));
      return;
    }
    heading(sect, 'H3', t('camp_plan_pdf_allergies_youth'));
    if (health.youth.length) {
      table(sect, [t('camp_plan_pdf_name'), t('camp_plan_pdf_allergy'), t('camp_plan_pdf_reaction_action')],
        health.youth.map((person) => [`${person.first_name} ${person.last_name}`,
          [person.allergies, person.epipen ? t('camp_plan_pdf_epipen') : null].filter(Boolean).join(' — '),
          // As the camp lists show it: the emergency medication may be the only instruction recorded.
          [person.reaction, person.action, person.emergency_medication].filter(Boolean).join(' — ')]));
    } else {
      paragraph(sect, t('camp_plan_pdf_none_declared'));
    }
    heading(sect, 'H3', t('camp_plan_pdf_allergies_adults'));
    if (health.adults.length) {
      table(sect, [t('camp_plan_pdf_name'), t('camp_plan_pdf_allergy'), t('camp_plan_pdf_person_to_notify')],
        health.adults.map((person) => [person.name,
          [person.allergies, person.carries_epipen ? t('camp_plan_pdf_epipen') : null].filter(Boolean).join(' — '),
          person.person_to_notify]));
    } else {
      paragraph(sect, t('camp_plan_pdf_none_declared'));
    }
  });

  section('camp_plan_pdf_material', (sect) => {
    const { items, free_text: freeText } = snapshot.material;
    if (!items.length && !freeText.length) {
      toComplete(sect);
      return;
    }
    if (items.length) {
      table(sect, [t('camp_plan_pdf_article'), t('camp_plan_pdf_quantity')],
        items.map((item) => [item.name, `${number(item.quantity)} ${t(`equipment_unit_${EQUIPMENT_UNITS.includes(item.unit_of_measure) ? item.unit_of_measure : 'each'}`)}`]));
    }
    freeText.forEach((entry) => paragraph(sect, `${entry.activity} — ${entry.material}`));
  });

  root.end();
  doc.end();
  return done;
}

/** The count a reason names, from the line's counts. */
function countsFor(reason, line, number) {
  const key = {
    sections_to_write: 'to_write', sections_to_review: 'to_review', days_without_activity: 'empty_days',
    days_without_title: 'untitled_days', consent_pending: 'pending', cite_transport: 'offers',
  }[reason];
  return key ? { count: number(line.counts?.[key]) } : {};
}

module.exports = { renderPlanPdf, PDF_LANGUAGES, translator };
